begin;
-- Explicit beta invitations for this transactional fixture.
insert into fontex_beta.invitations(email) values ('credit-admin@example.invalid'),('credit-budget@example.invalid'),('credit-user@example.invalid') on conflict(email) do update set enabled=true,expires_at=now()+interval '1 day';

create extension if not exists pgtap with schema extensions;
select extensions.no_plan();
insert into auth.users(id,email,raw_user_meta_data) values
 ('ac810000-0000-4000-8000-000000000001','credit-admin@example.invalid','{}'),
 ('ac810000-0000-4000-8000-000000000002','credit-user@example.invalid','{"is_admin":true,"role":"admin"}'),
 ('ac810000-0000-4000-8000-000000000003','credit-budget@example.invalid','{}');
insert into fontex_ai.admins(user_id) values('ac810000-0000-4000-8000-000000000001');
select extensions.is((select balance from fontex_ai.wallets where user_id='ac810000-0000-4000-8000-000000000003'),5,'signup receives exactly five initial credits');
select extensions.is((select count(*)::int from fontex_ai.events where user_id='ac810000-0000-4000-8000-000000000003' and kind='initial'),1,'initial grant is audited once');
select fontex_ai.ensure_wallet('ac810000-0000-4000-8000-000000000003');
select extensions.is((select count(*)::int from fontex_ai.events where user_id='ac810000-0000-4000-8000-000000000003' and kind='initial'),1,'reading or ensuring a wallet cannot repeat the initial grant');
-- Fixtures represent accounts with a verified email.
update auth.users set email_confirmed_at=now() where email in ('credit-admin@example.invalid','credit-budget@example.invalid','credit-user@example.invalid');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ac810000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select extensions.is((public.get_ai_credit_status()->>'balance')::int,5,'a signed-in user reads own balance');
select extensions.is((public.get_ai_credit_status()->>'is_admin')::boolean,false,'editable metadata cannot grant admin');
select extensions.throws_ok($$select public.admin_list_ai_accounts()$$,'42501',null,'nonadmin cannot list registered accounts');
select extensions.throws_ok($$select public.admin_grant_ai_credits('ac810000-0000-4000-8000-000000000002',100,'spoof',gen_random_uuid())$$,'42501',null,'nonadmin cannot grant self credits');
select extensions.throws_ok($$select fontex_ai.grant_credits('ac810000-0000-4000-8000-000000000002',100,'spoof',gen_random_uuid())$$,'42501',null,'private function has the same admin guard');
select extensions.throws_ok($$select public.reserve_ai_generation('ac810000-0000-4000-8000-000000000002',gen_random_uuid())$$,'42501',null,'client cannot call the service reservation RPC');
select extensions.throws_ok($$select public.finish_ai_generation(gen_random_uuid(),false)$$,'42501',null,'client cannot refund arbitrary requests');
select extensions.throws_ok($$update fontex_ai.wallets set balance=100 where user_id='ac810000-0000-4000-8000-000000000002'$$,'42501',null,'client cannot alter balances directly');
select extensions.throws_ok($$select * from fontex_ai.events$$,'42501',null,'client cannot read private audit rows');
select set_config('request.jwt.claims','{"sub":"ac810000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select extensions.is((public.get_ai_credit_status()->>'is_admin')::boolean,true,'database-authorized admin is recognized');
select extensions.is(jsonb_array_length(public.admin_list_ai_accounts('credit-user@example.invalid',25,0)->'accounts'),1,'admin can search a registered account by email');
select extensions.is((public.admin_grant_ai_credits('ac810000-0000-4000-8000-000000000002',3,'Beta','ac810001-0000-4000-8000-000000000001')->>'balance')::int,8,'admin grants additional credits');
select extensions.is((public.admin_grant_ai_credits('ac810000-0000-4000-8000-000000000002',3,'Beta','ac810001-0000-4000-8000-000000000001')->>'balance')::int,8,'network retry does not double a grant');
select extensions.throws_ok($$select public.admin_grant_ai_credits('ac810000-0000-4000-8000-000000000002',4,'Beta','ac810001-0000-4000-8000-000000000001')$$,'22023',null,'a reused grant key cannot change amount');
select extensions.is((public.admin_grant_ai_credits('ac810000-0000-4000-8000-000000000001',4,'Propio',gen_random_uuid())->>'balance')::int,9,'admin can top up own account');
select extensions.throws_ok($$select public.admin_grant_ai_credits('ac810000-0000-4000-8000-000000000002',0,'Beta',gen_random_uuid())$$,'22023',null,'zero credits is rejected');
select extensions.throws_ok($$select public.admin_grant_ai_credits('ac810000-0000-4000-8000-000000000002',1001,'Beta',gen_random_uuid())$$,'22023',null,'overlarge single grant is rejected');
select extensions.ok(jsonb_array_length(public.admin_ai_credit_history('ac810000-0000-4000-8000-000000000002'))>=2,'admin can audit grant history');
reset role;
set local role service_role;
select extensions.is((public.reserve_ai_generation('ac810000-0000-4000-8000-000000000003','ac810002-0000-4000-8000-000000000001')->>'balance')::int,4,'reservation holds one credit atomically');
select extensions.is(public.reserve_ai_generation('ac810000-0000-4000-8000-000000000003','ac810002-0000-4000-8000-000000000009')->>'reason','generation_busy','a parallel request cannot start another generation');
select extensions.is(public.finish_ai_generation('ac810002-0000-4000-8000-000000000001',true)->>'status','succeeded','valid proposal consumes its reserved credit');
select extensions.is((public.finish_ai_generation('ac810002-0000-4000-8000-000000000001',false)->>'balance')::int,4,'successful generation cannot later be refunded');
select extensions.is(public.reserve_ai_generation('ac810000-0000-4000-8000-000000000003','ac810002-0000-4000-8000-000000000001')->>'reason','duplicate_request','reservation id cannot be replayed');
select public.reserve_ai_generation('ac810000-0000-4000-8000-000000000003','ac810002-0000-4000-8000-000000000002');
select extensions.is((public.finish_ai_generation('ac810002-0000-4000-8000-000000000002',false)->>'balance')::int,4,'provider failure refunds the held credit');
select extensions.is((public.finish_ai_generation('ac810002-0000-4000-8000-000000000002',false)->>'balance')::int,4,'refund is idempotent');
select public.reserve_ai_generation('ac810000-0000-4000-8000-000000000003','ac810002-0000-4000-8000-000000000003');
reset role;
update fontex_ai.reservations set expires_at=now()-interval '1 second' where id='ac810002-0000-4000-8000-000000000003';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ac810000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select extensions.is((public.get_ai_credit_status()->>'balance')::int,4,'an interrupted request recovers after its lease expires');
select extensions.is((public.get_ai_credit_status()->>'active_generation')::boolean,false,'expired generation no longer blocks the account');
reset role;
set local role service_role;
select public.reserve_ai_generation('ac810000-0000-4000-8000-000000000003','ac810003-0000-4000-8000-000000000001');
select public.finish_ai_generation('ac810003-0000-4000-8000-000000000001',true);
select public.reserve_ai_generation('ac810000-0000-4000-8000-000000000003','ac810003-0000-4000-8000-000000000002');
select public.finish_ai_generation('ac810003-0000-4000-8000-000000000002',true);
select public.reserve_ai_generation('ac810000-0000-4000-8000-000000000003','ac810003-0000-4000-8000-000000000003');
select public.finish_ai_generation('ac810003-0000-4000-8000-000000000003',true);
select public.reserve_ai_generation('ac810000-0000-4000-8000-000000000003','ac810003-0000-4000-8000-000000000004');
select public.finish_ai_generation('ac810003-0000-4000-8000-000000000004',true);
select extensions.is(public.reserve_ai_generation('ac810000-0000-4000-8000-000000000003',gen_random_uuid())->>'reason','credits_exhausted','sixth completed generation is denied');
reset role;
update fontex_ai.wallets set updated_at=now()-interval '2 days' where user_id='ac810000-0000-4000-8000-000000000003';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ac810000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select extensions.is((public.get_ai_credit_status()->>'balance')::int,0,'credits do not reset daily');
select set_config('request.jwt.claims','{"sub":"ac810000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select extensions.is((public.get_ai_credit_status()->>'balance')::int,8,'another user keeps a separate balance');
reset role;
select extensions.ok(not has_function_privilege('anon','public.get_ai_credit_status()','execute'),'anonymous access is forbidden');
select extensions.ok(not has_function_privilege('authenticated','fontex_ai.ensure_wallet(uuid)','execute'),'wallet initialization is internal only');
select extensions.is((select count(*)::int from fontex_ai.reservations where user_id='ac810000-0000-4000-8000-000000000003' and status='succeeded'),5,'exactly five successful generations were recorded');
select * from extensions.finish();
rollback;
